const item = $input.first();
const binaries = item.binary || {};
const entries = Object.entries(binaries);
if (!entries.length) throw new Error('No uploaded files were received. Send multipart/form-data with one or more PDF files.');

const body = item.json?.body || {};
const supplied = String(body.batch_id || '').trim();
const batchId = /^[A-Za-z0-9_-]{8,100}$/.test(supplied)
  ? supplied
  : `pd02-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
const now = new Date();
const sd = $getWorkflowStaticData('global');
sd.pd02_v1 = sd.pd02_v1 || { batches: {} };

// Keep demo storage bounded: remove batches older than 24 hours, retain at most 50.
for (const [id, batch] of Object.entries(sd.pd02_v1.batches)) {
  const created = Date.parse(batch.created_at || 0);
  if (!Number.isFinite(created) || now.getTime() - created > 24 * 60 * 60 * 1000) delete sd.pd02_v1.batches[id];
}
const remaining = Object.entries(sd.pd02_v1.batches)
  .sort((a, b) => Date.parse(b[1].created_at || 0) - Date.parse(a[1].created_at || 0));
for (const [id] of remaining.slice(49)) delete sd.pd02_v1.batches[id];

sd.pd02_v1.batches[batchId] = {
  batch_id: batchId,
  status: 'processing',
  created_at: now.toISOString(),
  updated_at: now.toISOString(),
  total_files: entries.length,
  processed_files: 0,
  records: [],
  units: [],
  review_queue: [],
  stats: null,
  weekly_report_html: null,
};

return [{ json: { batch_id: batchId, total_files: entries.length }, binary: item.binary, pairedItem: { item: 0 } }];

const input = $input.first();
const binaries = input.binary || {};
const entries = Object.entries(binaries);
if (!entries.length) throw new Error('No uploaded files were found.');
const batchId = String(input.json.batch_id || '');
const totalFiles = entries.length;

return entries.map(([propertyName, file], index) => {
  const fileName = file.fileName || propertyName;
  // Extension from the FILENAME is reliable; n8n's fileExtension metadata is MIME-derived.
  const nameExt = String(fileName.split('.').pop() || '').toLowerCase();
  const metaExt = String(file.fileExtension || '').toLowerCase().split('/').pop();
  const extension = (nameExt && nameExt.length <= 6 && /^[a-z0-9]+$/.test(nameExt)) ? nameExt : metaExt;
  return {
    json: {
      batch_id: batchId,
      file_index: index,
      total_files: totalFiles,
      upload_property: propertyName,
      file_name: fileName,
      file_extension: extension,
      source_mime_type: file.mimeType || '',
      reported_file_size: file.fileSize || null,
    },
    binary: { data: file },
    pairedItem: { item: 0 },
  };
});

const source = $('Split Uploaded Files').item.json;

function findText(value, depth = 0) {
  if (depth > 6 || value == null) return '';
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) return value.map(v => findText(v, depth + 1)).filter(Boolean).join('\n');
  if (typeof value === 'object') {
    for (const key of ['text', 'pageContent', 'content', 'pages']) {
      if (Object.prototype.hasOwnProperty.call(value, key)) {
        const found = findText(value[key], depth + 1);
        if (found) return found;
      }
    }
  }
  return '';
}

const text = findText($json).trim();
const readError = text
  ? null
  : 'No text layer found in the PDF. It is likely a scanned image (OCR is a production-stage addition).';

return [{
  json: {
    file_input: {
      batch_id: source.batch_id,
      file_index: source.file_index,
      total_files: source.total_files,
      file_name: source.file_name,
      file_extension: 'pdf',
      source_mime_type: source.source_mime_type || 'application/pdf',
      text,
      read_status: text ? 'success' : 'failed',
      read_error: readError,
      reported_file_size: source.reported_file_size || null,
    },
    text,
    read_status: text ? 'success' : 'failed',
    read_error: readError,
  },
}];

const item = $input.first().json;
// Information Extractor outputs { output: <parsed JSON> } and DROPS the input
// metadata; the noOp path passes the raw file item through. Normalise both.
const ex = item.output || item;
const f = item.file_input || {};
// Metadata fallback: Split Uploaded Files is an ancestor of every loop branch
// (resolves per-iteration inside splitInBatches). Wrap for the noOp path.
let meta = {};
try { meta = $('Split Uploaded Files').item.json || {}; } catch (e) {}
try { if (!meta.batch_id && $('Normalise PDF Text').item.json.file_input) meta = $('Normalise PDF Text').item.json.file_input; } catch (e) {}
const batch_id = f.batch_id || item.batch_id || meta.batch_id || '';
const file_name = f.file_name || item.file_name || meta.file_name || 'unknown';
const file_index = f.file_index ?? item.file_index ?? meta.file_index ?? 0;
const file_extension = f.file_extension || item.file_extension || meta.file_extension || '';

const SDV2 = $getWorkflowStaticData('global');
const WATCH = (SDV2.pd02_v2 && SDV2.pd02_v2.watchlist) || {};
const MASTER = {};
for (const [devId, d] of Object.entries(WATCH)) {
  MASTER[devId] = {
    name_en: d.name_en || '', name_zh: d.name_zh || '', phase: d.phase_en || '',
    aliases: [d.name_en, d.name_zh, d.phase_en, d.phase_zh, d.district_en, d.district_zh].filter(Boolean),
  };
}
const NORM = s => String(s || '').toUpperCase().replace(/[^A-Z0-9\u4e00-\u9fff]+/g, '');
const normPhase = s => NORM(s).replace(/(PHASE|PH)\d*/g, '').replace(/第\d+期/g, '');

const normKey = (tower, floor, flat) => {
  const t = String(tower || '').toUpperCase().replace(/[^A-Z0-9]/g, '') || '?';
  const fl = String(floor || '').toUpperCase().replace(/[^0-9]/g, '') || '?';
  const fa = String(flat || '').toUpperCase().replace(/[^A-Z0-9]/g, '') || '?';
  return `${t}-${fl}F-${fa}`;
};
const num = v => { const n = Number(v); return Number.isFinite(n) ? n : null; };
const blank = v => (v === null || v === undefined || String(v).trim() === '') ? null : String(v).trim();

// --- REVIEW pass-through: unreadable scan / unsupported format ------------------
if (!ex.document_type && !ex.units && !ex.transactions) {
  const reasons = [];
  if (f.read_error) reasons.push(f.read_error);
  if (file_extension && file_extension !== 'pdf') reasons.push(`Unsupported format: .${file_extension}`);
  if (!reasons.length) reasons.push('Document could not be classified or extracted.');
  return [{ json: {
    batch_id,
    file_index,
    file_name,
    doc_type: null,
    development: null, development_name: null,
    confidence: null,
    doc_status: 'REVIEW',
    review_reasons: reasons,
    ai_guess: null,
    warnings: reasons,
    units: [],
    extracted_at: new Date().toISOString(),
  } }];
}

const docType = String(ex.document_type || '').trim();
let rawUnits = [];
if (docType === 'price_list') {
  rawUnits = (Array.isArray(ex.units) ? ex.units : []).map(u => ({
    tower: blank(u.tower), floor: blank(u.floor), flat: blank(u.flat),
    saleable_area_sqft: num(u.saleable_area_sqft), list_price: num(u.list_price),
    list_price_per_sqft: num(u.list_price_per_sqft), payment_plan: blank(u.payment_plan),
    status: 'offered',
  }));
} else if (docType === 'sales_arrangement') {
  rawUnits = (Array.isArray(ex.units) ? ex.units : []).map(u => ({
    tower: blank(u.tower), floor: blank(u.floor), flat: blank(u.flat),
    sale_date: blank(ex.sale_date), sales_method: blank(ex.sales_method),
    status: 'selling',
  }));
} else if (docType === 'transaction_register') {
  rawUnits = (Array.isArray(ex.transactions) ? ex.transactions : []).map(t => ({
    tower: blank(t.tower), floor: blank(t.floor), flat: blank(t.flat),
    saleable_area_sqft: num(t.saleable_area_sqft), transaction_date: blank(t.date),
    transaction_price: num(t.price), price_per_sqft: num(t.price_per_sqft),
    purchaser_type: blank(t.purchaser_type), remarks: blank(t.remarks),
    status: t.terminated === true || /terminat|cancel|已取消|撻訂/i.test(String(t.remarks || '')) ? 'terminated' : 'sold',
  }));
}

// --- Development matching against the watchlist (names + aliases) ---------------
const docDevName = blank(ex.development_name) || blank(ex.development);
let development = null;
let developmentName = null;
if (docDevName) {
  // Containment matching: extractor output varies ('HARBOUR VISTA 凱港峰 PHASE 1',
  // 'Harbour Vista Ph.1', '凱港峰' ...). Strip phase markers, then match either direction.
  const docN = normPhase(docDevName);
  for (const [code, dev] of Object.entries(MASTER)) {
    const names = [dev.name_en, dev.name_zh, ...(dev.aliases || [])].map(normPhase).filter(Boolean);
    const hit = names.some(n => docN === n || (n.length >= 4 && (docN.includes(n) || n.includes(docN))));
    if (hit) {
      development = code;
      developmentName = `${dev.name_en} ${dev.name_zh} ${dev.phase}`;
      break;
    }
  }
}

// --- Watchlist override: the monitor flow already knows the development ---
try {
  const ov = SDV2.pd02_v2 && SDV2.pd02_v2.file_meta && SDV2.pd02_v2.file_meta[batch_id]
    && SDV2.pd02_v2.file_meta[batch_id][file_name];
  if (ov && ov.development) {
    development = ov.development;
    developmentName = ov.development_name;
  }
} catch (e) {}

const confidence = num(ex.confidence);
const warnings = [];
if (confidence !== null && confidence < 0.9) warnings.push('Low confidence: manual confirmation required.');
if (!rawUnits.length) warnings.push('No units could be extracted from this document.');

const reviewReasons = [];
if (!development) reviewReasons.push(`Development not in watchlist${docDevName ? ` (best guess: ${docDevName})` : ''}.`);
if (confidence !== null && confidence < 0.7) reviewReasons.push(`Low extraction confidence (${Math.round(confidence * 100)}%).`);
if (f.read_error) reviewReasons.push(f.read_error);

const units = [];
const seen = new Set();
for (const u of rawUnits) {
  const uk = normKey(u.tower, u.floor, u.flat);
  const dupKey = `${uk}|${u.transaction_date || u.sale_date || ''}`;
  if (seen.has(dupKey)) continue;   // duplicate row inside one document
  seen.add(dupKey);
  units.push({ ...u, unit_key: uk, source_file: file_name });
}

return [{ json: {
  batch_id,
  file_index,
  file_name,
  doc_type: docType,
  development, development_name: developmentName,
  confidence,
  doc_status: reviewReasons.length ? 'REVIEW' : 'PROCESSED',
  review_reasons: reviewReasons,
  ai_guess: (reviewReasons.length && docDevName)
    ? { development: docDevName, reason: 'Development name did not match the watchlist master data.' }
    : null,
  warnings,
  units,
  extracted_at: new Date().toISOString(),
} }];

const record = $input.first().json;
const batchId = String(record.batch_id || '');
if (!batchId) throw new Error('Processed record is missing batch_id.');
const sd = $getWorkflowStaticData('global');
const batch = sd.pd02_v1?.batches?.[batchId];
if (!batch) return [{ json: { ...record, persisted: false, reason: 'Batch not found' } }];
batch.records = batch.records || [];
batch.records = batch.records.filter(r => r.file_name !== record.file_name);
batch.records.push(record);
batch.processed_files = batch.records.length;
batch.updated_at = new Date().toISOString();
return [{ json: { ...record, persisted: true } }];

// "Run Once for All Items": every file's record arrives here after the loop.
const records = $input.all().map(i => i.json).filter(r => r && r.file_name);
const batchId = records[0]?.batch_id || '';

const SDV2 = $getWorkflowStaticData('global');
const WATCH = (SDV2.pd02_v2 && SDV2.pd02_v2.watchlist) || {};
const MASTER = {};
for (const [devId, d] of Object.entries(WATCH)) {
  MASTER[devId] = {
    name_en: d.name_en || '', name_zh: d.name_zh || '', phase: d.phase_en || '',
    aliases: [d.name_en, d.name_zh, d.phase_en, d.phase_zh, d.district_en, d.district_zh].filter(Boolean),
  };
}
const FUNNEL = { sold: 3, terminated: 3, selling: 2, offered: 1 };
const units = new Map();          // `${development}|${unit_key}` -> current state
const reviewQueue = [];
let duplicatesDetected = 0;
let unlistedCount = 0;
const dupQueueFiles = new Set(); // one queue entry per duplicate FILE, not per unit

// Latest price-list revision per development (No.3R supersedes No.3).
const plByDev = {};
for (const r of records) {
  if (r.doc_type === 'price_list' && r.development) {
    plByDev[r.development] = plByDev[r.development] || [];
    plByDev[r.development].push(r);
  }
}
for (const pls of Object.values(plByDev)) {
  pls.sort((a, b) => (/R/i.test(a.price_list_no || '') ? 1 : 0) - (/R/i.test(b.price_list_no || '') ? 1 : 0));
}

for (const r of records) {
  if (r.doc_status === 'REVIEW' || !r.development) {
    reviewQueue.push({
      file_name: r.file_name,
      doc_type: r.doc_type || 'unreadable',
      development: r.development || null,
      development_name: r.development_name || null,
      confidence: r.confidence ?? null,
      review_reasons: r.review_reasons?.length ? r.review_reasons : ['Development not matched or document unreadable.'],
      ai_guess: r.ai_guess,
    });
    continue;
  }
  const plsForDev = plByDev[r.development] || [];
  const currentPl = plsForDev[plsForDev.length - 1] || null;
  const onCurrentPl = u => currentPl && (currentPl.units || []).some(x => x.unit_key === u.unit_key);

  for (const u of (r.units || [])) {
    const key = `${r.development}|${u.unit_key}`;
    const entry = {
      unit_key: u.unit_key, tower: u.tower, floor: u.floor, flat: u.flat,
      development: r.development, development_name: r.development_name,
      saleable_area_sqft: u.saleable_area_sqft ?? null,
      list_price: u.list_price ?? null, list_price_per_sqft: u.list_price_per_sqft ?? null,
      payment_plan: u.payment_plan ?? null,
      sale_date: u.sale_date ?? null, sales_method: u.sales_method ?? null,
      transaction_date: u.transaction_date ?? null, transaction_price: u.transaction_price ?? null,
      price_per_sqft: u.price_per_sqft ?? null, purchaser_type: u.purchaser_type ?? null,
      status: u.status,
      source_file: r.file_name, source_doc_type: r.doc_type,
      confidence: r.confidence ?? null,
      duplicate_of: null, unlisted_unit: false, superseded_by: null,
      history: [],
    };

    // DUPLICATE: same doc type + same unit + same event date (e.g. register grabbed twice).
    const prev = units.get(key);
    if (prev && prev.source_doc_type === r.doc_type && (prev.transaction_date || prev.sale_date) === (u.transaction_date || u.sale_date)) {
      duplicatesDetected += 1;
      prev.duplicate_of = prev.duplicate_of || prev.source_file;
      if (!dupQueueFiles.has(r.file_name)) {
        dupQueueFiles.add(r.file_name);
        reviewQueue.push({
          file_name: r.file_name, doc_type: r.doc_type, development: r.development,
          review_reasons: [`Duplicate of ${prev.source_file} — same ${r.doc_type} for ${u.unit_key} on same date. Not double-counted.`],
          ai_guess: null, duplicate: true,
        });
      }
      continue;
    }

    if (!prev) {
      // Register-only unit never seen on a price list -> flag (staff sales happen).
      if (r.doc_type === 'transaction_register' && !plsForDev.some(p => (p.units || []).some(x => x.unit_key === u.unit_key))) {
        entry.unlisted_unit = true;
        unlistedCount += 1;
      }
      units.set(key, entry);
      continue;
    }

    const prevOrder = FUNNEL[prev.status] || 0;
    const newOrder = FUNNEL[u.status] || 0;
    if (newOrder > prevOrder) {
      // Funnel rule: sold/terminated beats selling beats offered. Latest truth wins.
      prev.history.push({
        status: prev.status, date: prev.transaction_date || prev.sale_date || null,
        price: prev.transaction_price ?? prev.list_price ?? null, source_file: prev.source_file,
      });
      for (const k of ['sale_date', 'sales_method', 'transaction_date', 'transaction_price',
                       'price_per_sqft', 'purchaser_type', 'saleable_area_sqft', 'list_price',
                       'list_price_per_sqft', 'payment_plan', 'status', 'source_file',
                       'source_doc_type', 'confidence']) {
        if (entry[k] !== undefined && entry[k] !== null) prev[k] = entry[k];
      }
      if (r.doc_type === 'transaction_register' && !onCurrentPl(u) && !prev.unlisted_unit) {
        prev.unlisted_unit = true;
        unlistedCount += 1;
      }
    } else {
      // Same or earlier funnel stage: only fill missing catalogue data (order-independent).
      if (prev.status === 'offered' && u.status === 'offered' && u.list_price != null) {
        prev.list_price = u.list_price;                    // revised price list wins
        prev.list_price_per_sqft = u.list_price_per_sqft ?? prev.list_price_per_sqft;
        prev.payment_plan = u.payment_plan ?? prev.payment_plan;
        if (prev.source_file !== r.file_name) prev.superseded_by = r.file_name;
      } else {
        if (prev.list_price == null && u.list_price != null) prev.list_price = u.list_price;
        if (prev.saleable_area_sqft == null && u.saleable_area_sqft != null) prev.saleable_area_sqft = u.saleable_area_sqft;
      }
      prev.history.push({
        status: u.status, date: u.transaction_date || u.sale_date || null,
        price: u.transaction_price ?? u.list_price ?? null, source_file: r.file_name,
      });
    }
  }
}

// ---- stats ----------------------------------------------------------------------
const unitList = [...units.values()];
const soldUnits = unitList.filter(u => u.status === 'sold');
const stats = {
  documents_processed: records.length,
  documents_reviewed: reviewQueue.length,
  duplicates_detected: duplicatesDetected,
  duplicate_files: dupQueueFiles.size,
  unlisted_units: unlistedCount,
  sold_total: soldUnits.length,
  terminated_total: unitList.filter(u => u.status === 'terminated').length,
  per_development: {},
};
const allSumPrice = soldUnits.reduce((s, u) => s + (u.transaction_price || 0), 0);
const allSumArea = soldUnits.reduce((s, u) => s + (u.saleable_area_sqft || 0), 0);
let totalBase = 0;
for (const code of Object.keys(MASTER)) {
  const devUnits = unitList.filter(u => u.development === code);
  const offered = devUnits.filter(u => u.status === 'offered').length;
  const selling = devUnits.filter(u => u.status === 'selling').length;
  const sold = devUnits.filter(u => u.status === 'sold').length;
  const terminated = devUnits.filter(u => u.status === 'terminated').length;
  const base = offered + selling + sold + terminated;       // full catalogue size
  totalBase += base;
  const soldSub = devUnits.filter(u => u.status === 'sold');
  const sumPrice = soldSub.reduce((s, u) => s + (u.transaction_price || 0), 0);
  const sumArea = soldSub.reduce((s, u) => s + (u.saleable_area_sqft || 0), 0);
  stats.per_development[code] = {
    development_name: `${MASTER[code].name_en} ${MASTER[code].name_zh} ${MASTER[code].phase}`,
    offered, selling, sold, terminated,
    take_up_pct: base ? Math.round((sold / base) * 1000) / 10 : 0,
    avg_price_psf: sumArea ? Math.round(sumPrice / sumArea) : null,
    avg_transaction_price: soldSub.length ? Math.round(sumPrice / soldSub.length) : null,
  };
}
stats.take_up_pct = totalBase ? Math.round((stats.sold_total / totalBase) * 1000) / 10 : 0;
stats.avg_price_psf = allSumArea ? Math.round(allSumPrice / allSumArea) : null;
stats.avg_transaction_price = soldUnits.length ? Math.round(allSumPrice / soldUnits.length) : null;

// persist into the batch (frontend endpoints read from here)
const sd = $getWorkflowStaticData('global');
const batch = sd.pd02_v1?.batches?.[batchId];
if (batch) {
  batch.units = unitList;
  batch.review_queue = reviewQueue;
  batch.stats = stats;
  batch.updated_at = new Date().toISOString();
}

return [{ json: { batch_id: batchId, units: unitList, review_queue: reviewQueue, stats } }];

const data = $input.first().json;
return (data.units || []).map(u => ({ json: {
  unit_key: u.unit_key, development: u.development, development_name: u.development_name,
  tower: u.tower, floor: u.floor, flat: u.flat,
  saleable_area_sqft: u.saleable_area_sqft, list_price: u.list_price,
  list_price_per_sqft: u.list_price_per_sqft, payment_plan: u.payment_plan,
  sale_date: u.sale_date, sales_method: u.sales_method,
  transaction_date: u.transaction_date, transaction_price: u.transaction_price,
  price_per_sqft: u.price_per_sqft, purchaser_type: u.purchaser_type,
  status: u.status, source_file: u.source_file,
  unlisted_unit: u.unlisted_unit === true, duplicate_of: u.duplicate_of,
} }));

// "Run Once for All Items". Deterministic arithmetic + HTML — no LLM on the numbers.
const data = $('Reconcile Unit Records').item.json;
const batchId = data.batch_id || '';
const units = data.units || [];
const reviewQueue = data.review_queue || [];
const stats = data.stats || {};
const dev = stats.per_development || {};

const hkf = n => n == null ? '—' : 'HK$' + Number(n).toLocaleString('en-HK');
const hknum = n => n == null ? '—' : Number(n).toLocaleString('en-HK');
const pct = n => n == null ? '—' : Number(n) + '%';
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// --- weekly trend: ISO week per transaction date --------------------------------
const isoWeek = d => {
  const date = new Date(d + 'T00:00:00Z');
  const day = (date.getUTCDay() + 6) % 7;
  date.setUTCDate(date.getUTCDate() - day + 3);
  const firstThursday = new Date(Date.UTC(date.getUTCFullYear(), 0, 4));
  const fDay = (firstThursday.getUTCDay() + 6) % 7;
  firstThursday.setUTCDate(firstThursday.getUTCDate() - fDay + 3);
  const week = 1 + Math.round((date - firstThursday) / (7 * 24 * 3600 * 1000));
  return `W${week} ${date.getUTCFullYear()}`;
};
const trend = {};
for (const u of units) {
  if (u.status === 'sold' && u.transaction_date) {
    const w = isoWeek(u.transaction_date);
    trend[w] = (trend[w] || 0) + 1;
  }
}
const trendLabels = Object.keys(trend).sort();
const trendValues = trendLabels.map(w => trend[w]);

// --- unit mix by flat size band --------------------------------------------------
const bands = { '<300': 0, '300–500': 0, '>500': 0 };
for (const u of units) {
  if (u.status !== 'sold' || !u.saleable_area_sqft) continue;
  const a = u.saleable_area_sqft;
  if (a < 300) bands['<300'] += 1;
  else if (a <= 500) bands['300–500'] += 1;
  else bands['>500'] += 1;
}

// --- KPI cards -------------------------------------------------------------------
const kpis = [
  ['Units sold this week', String(stats.sold_total ?? 0), '週內成交單位'],
  ['Take-up', pct(stats.take_up_pct), '已售比例'],
  ['Avg price / sq ft', stats.avg_price_psf == null ? '—' : 'HK$' + hknum(stats.avg_price_psf), '平均呎價'],
  ['Terminations', String(stats.terminated_total ?? 0), '撻訂'],
  ['Documents processed', String(stats.documents_processed ?? 0), '處理文件'],
