const lastBatchId = v2.last_check && v2.last_check.batch_id;
if (lastBatchId && sd.pd02_v1 && sd.pd02_v1.batches[lastBatchId]) {
  const b = sd.pd02_v1.batches[lastBatchId];
  latest_batch = {
    batch_id: b.batch_id,
    status: b.status,
    total_files: b.total_files,
    processed_files: b.processed_files,
    unit_count: (b.units || []).length,
    review_count: (b.review_queue || []).length,
    stats: b.stats || null,
    created_at: b.created_at,
    origin: b.origin || 'intake',
  };
}
return [{ json: {
  ok: true,
  watchlist,
  inventory,
  developments: {
    count: (v2.developments || []).length,
    refreshed_at: v2.developments_refreshed_at || null,
  },
  last_check: v2.last_check || null,
  check_log: (v2.check_log || []).slice(0, 20),
  latest_batch,
  _status: 200,
} }];

// Real SRPE price lists hold hundreds of rows; one LLM call cannot reliably
// emit them all. Split into ~15k-char chunks (with overlap) for per-chunk extraction.
const item = $input.first().json;
const text = String(item.text || '');
const CHUNK = 15000;
const OVERLAP = 1000;
if (!text.trim()) return [{ json: { ...item, chunk_index: 0, chunk_total: 1, text } }];
if (text.length <= CHUNK) return [{ json: { ...item, chunk_index: 0, chunk_total: 1, text } }];
const chunks = [];
let i = 0;
while (i < text.length) {
  let end = Math.min(i + CHUNK, text.length);
  if (end < text.length) {
    const nl = text.lastIndexOf('\n', end);
    if (nl > i + CHUNK * 0.7) end = nl;
  }
  chunks.push(text.slice(i, end));
  if (end === text.length) break;   // tail done — avoid degenerate 1-char steps
  i = Math.max(end - OVERLAP, i + 1);
}
return chunks.map((c, k) => ({ json: { ...item, chunk_index: k, chunk_total: chunks.length, text: c } }));

// "Run Once for All Items": merge per-chunk extractions into one price-list record.
const items = $input.all().map(i => i.json);
const merged = {
  document_type: 'price_list',
  development: null, development_name: null,
  price_list_no: null, price_list_date: null, currency: null, payment_plan: null,
  units: [],
};
const seen = new Set();
for (const it of items) {
  const ex = it.output || it;
  for (const k of ['development', 'development_name', 'price_list_no', 'price_list_date', 'currency', 'payment_plan']) {
    if (merged[k] == null && ex[k] != null) merged[k] = ex[k];
  }
  for (const u of (ex.units || [])) {
    if (!u || !u.unit_key) continue;
    if (seen.has(u.unit_key)) continue;   // overlapping chunks may duplicate a row
    seen.add(u.unit_key);
    merged.units.push(u);
  }
}
return [{ json: { output: merged, file_input: items[0] && items[0].file_input } }];
